import {badaoFixture} from './badao-fixture.mjs';
export const EARTH_CONFIG={version:'training-earth-v1',rewardPolicy:'none',unlockLevel:20,mpCost:'10',cooldownUs:2000000,durationUs:600000,nodeOffsetsUs:[100000,200000,300000,400000],rangeX:500000,rangeY:500000,displacement:3000,damage:{base:'0',growth:'0',coefficient:{n:'1',d:'1'},nodeWeights:[1,1,1,1]},bleed:{coefficient:{n:'1',d:'1'},nodeWeights:[1,1,1,1],jumps:5,intervalUs:100000},knockdownThreshold:{n:'1',d:'1'},knockdownDurationUs:500000};
export async function earthFixture(patch={}){const h=await badaoFixture({schemaVersion:5,profile:'local-test-earth',capabilities:['basic','cross','bengshan','badao','earth','no-rewards'],earth:structuredClone(EARTH_CONFIG),...patch});const grow=h.grow;return {...h,grow:(level=20)=>grow(level)};}
